/*
 * 74HC00 NAND Gate Test
 * Two buttons on D2, D3 control inputs A1, B1 of gate 1.
 * Output Y1 drives an LED.
 *
 * NAND Truth Table:  Y = !(A & B)
 *   A=0, B=0  →  Y=1  (LED ON)
 *   A=0, B=1  →  Y=1  (LED ON)
 *   A=1, B=0  →  Y=1  (LED ON)
 *   A=1, B=1  →  Y=0  (LED OFF)
 *
 * Wiring:
 *   D2 → Button1 → GND   (input A1, internal pull-up)
 *   D3 → Button2 → GND   (input B1, internal pull-up)
 *   74HC00 VCC → 5V, GND → GND
 *   74HC00 Y1 → LED → 220Ω → GND
 */

int pinA = 2;
int pinB = 3;
int ledPin = 13;

void setup() {
  pinMode(pinA, INPUT_PULLUP);
  pinMode(pinB, INPUT_PULLUP);
  pinMode(ledPin, OUTPUT);
  Serial.begin(115200);
  Serial.println("NAND gate test ready");
}

void loop() {
  int a = digitalRead(pinA);  // LOW = button pressed = logic 1 (active LOW)
  int b = digitalRead(pinB);

  // Buttons are active LOW (pressed = 0), so invert for NAND logic
  int logicA = (a == LOW) ? 1 : 0;
  int logicB = (b == LOW) ? 1 : 0;

  // NAND: output is LOW only when both inputs are HIGH
  int nandOut = (logicA & logicB) ? LOW : HIGH;

  digitalWrite(ledPin, nandOut);

  Serial.print("A=");
  Serial.print(logicA);
  Serial.print(" B=");
  Serial.print(logicB);
  Serial.print(" → Y=");
  Serial.println(nandOut == HIGH ? "1 (ON)" : "0 (OFF)");

  delay(100);
}
